"""Plot one or two ModelFoc.log files generated by the FOC model csim."""

import argparse
import bisect
import math
import sys
from dataclasses import dataclass
from pathlib import Path
from typing import Dict, List, Optional, Sequence

import matplotlib.pyplot as plt


REQUIRED_COLUMNS = (
    "w",
    "theta_r",
    "control_mode",
    "va",
    "vb",
    "vc",
    "out_va",
    "out_vb",
    "out_vc",
    "Va_cmd",
    "Vb_cmd",
    "Vc_cmd",
)

# The FP32 model testbench writes ModelFoc rows without the otherwise identical
# header emitted by the ap_fixed testbench. The empty element is the plant/FOC
# visual separator inserted by model logging.
MODEL_FOC_RAW_HEADER = (
    "N Ld Lq Rs fai_m J TL_th TL dt_sim Umax va vb vc Valpha Vbeta cos_theta_in "
    "sin_theta_in Va_cos Vb_sin Vb_cos Va_sin vd vq v0 w theta_r Id Iq theta_e "
    "dId_dt dIq_dt Te dw_dt BEMF_d BEMF_q w_next theta_r_next Id_next Iq_next "
    "out_va out_vb out_vc"
).split() + [""] + (
    "ppr cpr II_sample control_mode fixperiod flux_sp flux_kp flux_ki flux_kd "
    "torque_sp torque_kp torque_ki torque_kd rpm_sp rpm_kp rpm_ki rpm_kd angle_sh "
    "vd vq trigger control2 fw_kp fw_ki id flux_acc flux_err flux_out iq torque_acc "
    "torque_err torque_out rpm rpm_acc rpm_err rpm_out angle Va_cmd Vb_cmd Vc_cmd "
    "Ialpha Ibeta Ihomopolar rip_cnt fixed_angle_args"
).split()

DISPLAY_NAMES = {
    "va": "Va",
    "vb": "Vb",
    "vc": "Vc",
    "out_va": "Ia",
    "out_vb": "Ib",
    "out_vc": "Ic",
}


@dataclass
class ModelFocLog:
    """Parsed ModelFoc waveform data."""

    path: Path
    time_s: List[float]
    columns: Dict[str, List[float]]

    @property
    def motor_rpm(self) -> List[float]:
        return [value * 60.0 / (2.0 * math.pi) for value in self.columns["w"]]


def _unique_names(names: Sequence[str]) -> List[str]:
    """Disambiguate repeated names in the tab-separated header."""
    counts: Dict[str, int] = {}
    result = []
    for name in names:
        count = counts.get(name, 0)
        counts[name] = count + 1
        result.append(name if count == 0 else f"{name}_{count + 1}")
    return result


def read_model_foc(path: Path) -> ModelFocLog:
    """Read the MM2_B_Time tab-separated waveform format."""
    header: List[str] = []
    value_indexes: List[int] = []
    time_s: List[float] = []
    rows: List[List[float]] = []

    with path.open(encoding="utf-8") as log_file:
        for line_number, line in enumerate(log_file, start=1):
            if not line.startswith("MM2_B_Time is"):
                continue
            fields = line.rstrip("\n").split("\t")
            if len(fields) < 4 or fields[-1].strip() != "MM2_E":
                continue

            if not header:
                raw_header = [field.strip() for field in fields[2:-1]]
                if raw_header[0] != "N":
                    # FP32 model logs start directly with the first sample.
                    raw_header = MODEL_FOC_RAW_HEADER
                value_indexes = [index for index, name in enumerate(raw_header) if name]
                header = _unique_names([raw_header[index] for index in value_indexes])
                if raw_header[0] == "N":
                    continue

            try:
                time_s.append(float(fields[1].strip().removesuffix("(s)")))
                values = fields[2:-1]
                row = [float(values[index].strip()) for index in value_indexes]
            except ValueError as error:
                raise ValueError(f"{path}:{line_number}: cannot parse waveform row") from error
            if len(row) != len(header):
                raise ValueError(f"{path}:{line_number}: header/data column count mismatch")
            rows.append(row)

    if not header or not rows:
        raise ValueError(f"{path}: no ModelFoc waveform rows found")

    missing = [column for column in REQUIRED_COLUMNS if column not in header]
    if missing:
        raise ValueError(f"{path}: required columns are missing: {', '.join(missing)}")

    columns = {name: [row[index] for row in rows] for index, name in enumerate(header)}
    return ModelFocLog(path=path, time_s=time_s, columns=columns)


def interpolate(time_s: Sequence[float], values: Sequence[float], target_time_s: float) -> float:
    """Linearly interpolate a trace, clamping outside its time range."""
    index = bisect.bisect_left(time_s, target_time_s)
    if index == 0:
        return values[0]
    if index >= len(time_s):
        return values[-1]

    before_time = time_s[index - 1]
    after_time = time_s[index]
    ratio = (target_time_s - before_time) / (after_time - before_time)
    return values[index - 1] + ratio * (values[index] - values[index - 1])


def default_output_path(log_path: Path) -> Path:
    """Place generated images in the testcase directory, not the HLS build tree."""
    for directory in log_path.parents:
        if directory.name == "hls" and directory.parent.parent.exists():
            return directory.parent.parent / f"{log_path.stem}_waveforms.png"
    return log_path.parent / f"{log_path.stem}_waveforms.png"


def plot_three_phase(
    axis: plt.Axes,
    time_ms: Sequence[float],
    trace: ModelFocLog,
    channels: Sequence[str],
    title: str,
    y_label: str,
    reference: Optional[ModelFocLog],
    label: str,
    reference_label: str,
) -> None:
    """Plot three phases, overlaying a reference trace when supplied."""
    colors = ("#2563eb", "#0f766e", "#c2410c")
    for channel, color in zip(channels, colors):
        channel_label = DISPLAY_NAMES.get(channel, channel)
        axis.plot(time_ms, trace.columns[channel], color=color, label=f"{label} {channel_label}")
        if reference:
            axis.plot(
                [time * 1000.0 for time in reference.time_s],
                reference.columns[channel],
                color=color,
                linestyle="--",
                alpha=0.8,
                label=f"{reference_label} {channel_label}",
            )
    axis.set_title(title)
    axis.set_ylabel(y_label)
    axis.grid(True, alpha=0.3)
    axis.legend(ncol=3, fontsize=8, loc="best")


def add_mode_regions(axis: plt.Axes, trace: ModelFocLog) -> None:
    """Mark contiguous control-mode ranges using lightly shaded backgrounds."""
    modes = trace.columns["control_mode"]
    region_start = 0
    palette = ("#dbeafe", "#dcfce7", "#ffedd5", "#fce7f3", "#ede9fe")

    for index in range(1, len(modes) + 1):
        if index != len(modes) and modes[index] == modes[region_start]:
            continue
        start_ms = trace.time_s[region_start] * 1000.0
        end_ms = trace.time_s[index - 1] * 1000.0
        color = palette[int(modes[region_start]) % len(palette)]
        axis.axvspan(start_ms, end_ms, color=color, alpha=0.35, zorder=0)
        axis.text(
            (start_ms + end_ms) / 2.0,
            0.97,
            f"mode {int(modes[region_start])}",
            transform=axis.get_xaxis_transform(),
            ha="center",
            va="top",
            fontsize=8,
        )
        region_start = index


def plot_logs(
    primary: ModelFocLog,
    reference: Optional[ModelFocLog],
    primary_label: str,
    reference_label: str,
    output: Path,
    show: bool,
) -> None:
    """Create closed-loop command, feedback, and optional error plots."""
    rows = 5 if reference else 4
    figure, axes = plt.subplots(rows, 1, figsize=(14, 3.4 * rows), sharex=True, constrained_layout=True)
    if rows == 1:
        axes = [axes]
    time_ms = [time * 1000.0 for time in primary.time_s]

    axes[0].plot(time_ms, primary.motor_rpm, color="#2563eb", label=primary_label)
    if reference:
        axes[0].plot(
            [time * 1000.0 for time in reference.time_s],
            reference.motor_rpm,
            color="#c2410c",
            linestyle="--",
            label=reference_label,
        )
    axes[0].set_title("Motor speed")
    axes[0].set_ylabel("Speed (rpm)")
    axes[0].grid(True, alpha=0.3)
    axes[0].legend(loc="best")
    add_mode_regions(axes[0], primary)

    axes[1].plot(time_ms, primary.columns["theta_r"], color="#2563eb", label=primary_label)
    if reference:
        axes[1].plot(
            [time * 1000.0 for time in reference.time_s],
            reference.columns["theta_r"],
            color="#c2410c",
            linestyle="--",
            label=reference_label,
        )
    axes[1].set_title("Mechanical rotor position")
    axes[1].set_ylabel("Position (rad)")
    axes[1].grid(True, alpha=0.3)
    axes[1].legend(loc="best")

    plot_three_phase(
        axes[2],
        time_ms,
        primary,
        ("va", "vb", "vc"),
        "Command path: FOC output / virtual-motor input voltage",
        "Voltage (V)",
        reference,
        primary_label,
        reference_label,
    )
    plot_three_phase(
        axes[3],
        time_ms,
        primary,
        ("out_va", "out_vb", "out_vc"),
        "Feedback path: virtual-motor output / FOC input current",
        "Current (A)",
        reference,
        primary_label,
        reference_label,
    )

    if reference:
        colors = ("#2563eb", "#0f766e", "#c2410c")
        for channel, color in zip(("Va_cmd", "Vb_cmd", "Vc_cmd"), colors):
            differences = [
                value - interpolate(reference.time_s, reference.columns[channel], time)
                for time, value in zip(primary.time_s, primary.columns[channel])
            ]
            max_error = max(abs(value) for value in differences)
            axes[4].plot(time_ms, differences, color=color, label=f"Δ{channel}, max={max_error:.4g} V")
        axes[4].set_title("FOC output difference: primary − reference")
        axes[4].set_ylabel("Difference (V)")
        axes[4].grid(True, alpha=0.3)
        axes[4].legend(ncol=3, fontsize=8, loc="best")

    axes[-1].set_xlabel("Simulation time (ms)")
    figure.suptitle(f"FOC Model CSIM waveform: {primary.path.name}", fontsize=14)
    output.parent.mkdir(parents=True, exist_ok=True)
    figure.savefig(output, dpi=160)
    print(f"Wrote {output}")
    if show:
        plt.show()
    plt.close(figure)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Plot one ModelFoc.log, or compare a primary log against a reference log."
    )
    parser.add_argument("primary", type=Path, help="Primary ModelFoc.log, for example the ap_fixed result")
    parser.add_argument(
        "reference",
        type=Path,
        nargs="?",
        help="Optional golden/reference ModelFoc.log; its traces are overlaid as dashed lines",
    )
    parser.add_argument("--primary-label", default="Primary", help="Legend label for the primary log")
    parser.add_argument("--reference-label", default="Reference", help="Legend label for the reference log")
    parser.add_argument(
        "--output",
        type=Path,
        help="Output PNG path (default: primary log's testcase directory)",
    )
    parser.add_argument("--show", action="store_true", help="Open the matplotlib window after writing the PNG")
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    try:
        primary = read_model_foc(args.primary)
        reference = read_model_foc(args.reference) if args.reference else None
        output = args.output or default_output_path(primary.path)
        plot_logs(primary, reference, args.primary_label, args.reference_label, output, args.show)
    except (OSError, ValueError) as error:
        print(f"error: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
